const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',check:'<rect x="3" y="4" width="18" height="17" rx="3"/><path d="m8 12 3 3 5-6"/>',lightbulb:'<path d="M9 18h6m-5 4h4M8 15a7 7 0 1 1 8 0l-1 3H9z"/>',calculator:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M9 11h1m4 0h1m-6 4h1m4 0h1m-6 4h1m4 0h1"/>',note:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',sheet:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M3 15h18M9 3v18M15 3v18"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',invest:'<path d="M3 18 9 12l4 3 8-9M15 6h6v6"/>',grid:'<rect x="3" y="3" width="8" height="8" rx="2"/><rect x="13" y="3" width="8" height="8" rx="2"/><rect x="3" y="13" width="8" height="8" rx="2"/><rect x="13" y="13" width="8" height="8" rx="2"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 5 3 11 8 15 5-4 12-10 8-15z"/>',settings:'<path d="M12 2v3m0 14v3M2 12h3m14 0h3M4.9 4.9 7 7m10 10 2.1 2.1M19.1 4.9 17 7M7 17l-2.1 2.1"/><circle cx="12" cy="12" r="4"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 4h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',trash:'<path d="M4 7h16M10 4h4M6 7l1 14h10l1-14M10 11v6m4-6v6"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',chevron:'<path d="m9 18 6-6-6-6"/>',left:'<path d="m15 18-6-6 6-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',upload:'<path d="M12 17V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',save:'<path d="M4 4h13l3 3v13H4zM8 4v6h8V4M8 20v-7h8v7"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-5 16-5 16 0"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',logout:'<path d="M9 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h4M16 17l5-5-5-5M21 12H9"/>',edit:'<path d="M4 20h4l12-12-4-4L4 16zM14 6l4 4"/>',file:'<path d="M5 2h9l5 5v15H5zM14 2v6h5"/>'};
const ic=(name,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.note}</svg>`;
const navItems=[['home','Início','home'],['tasks','Rotinas','check'],['ideas','Ideias','lightbulb'],['calculator','Calculadora','calculator'],['notes','Anotações','note'],['sheets','Planilhas','sheet'],['calendar','Datas e eventos','calendar'],['invest','Investimentos','invest'],['mix','Área mista','grid'],['donation','Donation','heart'],['help','Guia das funções','help'],['settings','Configurações','settings']];
const titles=Object.fromEntries(navItems.map(x=>[x[0],x[1]]));
let savedWordRange=null;let route='home',noteTab='keep',investTab='planner',selectedMonth=new Date().getMonth(),selectedYear=new Date().getFullYear(),selectedDay=localDate(),activeDoc=null,activeBook=null,activeSheet=0,activeCell='A1',showAllDocs=false,searchTasks='',statusTasks='all',calcText='0',calcResult='',calcHist='',docTimer,saveTimer,editPending=false,authTab='login';
const curr=()=>db.getPrefs();
function navigate(next){route=next;activeDoc=null;activeBook=null;$('#sidebar').classList.remove('open');$('#sidebar-scrim').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})}
function notify(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;$('#toast-root').append(el);setTimeout(()=>el.remove(),3500)}
function download(filename,data,type='application/json'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function ask({title='Confirmar',body='',confirm='Excluir',onConfirm}){$('#modal-root').innerHTML=`<div class="modal-overlay"><div class="modal"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal">${ic('close')}</button></div><p class="muted" style="line-height:1.7">${esc(body)}</p><div class="form-row" style="justify-content:flex-end"><button class="btn" data-action="close-modal">Cancelar</button><button class="btn btn-primary" id="modal-confirm">${esc(confirm)}</button></div></div></div>`;$('#modal-confirm').onclick=()=>{closeModal();onConfirm?.()}}
function closeModal(){$('#modal-root').innerHTML=''}
function heading(title,subtitle,action=''){return `<div class="page-heading fade-rise"><div><div class="eyebrow">ZORK / ORGANIZA</div><h1>${title}</h1><p>${subtitle}</p></div>${action?`<div class="heading-actions">${action}</div>`:''}</div>`}
function pill(text){return `<span class="pill">${esc(text)}</span>`}
function empty(msg,description){return `<div class="empty"><div class="empty-icon">✧</div><strong>${esc(msg)}</strong><p>${esc(description)}</p></div>`}
function renderNav(){const n=$('#nav');n.innerHTML=navItems.map(([key,label,icon],i)=>`${i===9||i===10?'<div class="nav-divider"></div>':''}<button class="nav-item ${route===key?'active':''}" data-route="${key}">${ic(icon)}<span>${label}</span></button>`).join('');const user=db.currentUser();$('#account-mini').innerHTML=`<div class="avatar">${user?esc((user.displayName||user.email||'U')[0].toUpperCase()):'Z'}</div><span><strong>${user?esc(user.displayName||user.email?.split('@')[0]||'Minha conta'):'Visitante'}</strong><small>${user?'Conta conectada':'Conta e sincronização'}</small></span><span class="mini-arrow">›</span>`;$('#account-top').textContent=user?(user.displayName||user.email||'U')[0].toUpperCase():'Z';$('#backup-state').innerHTML=`<span class="state-dot"></span><span>${user?(db.cloudReady()?'Sincronizado com nuvem':'Conectando à nuvem…'):'Salvo neste navegador'}</span>`}
function render(){if(isEditing()){editPending=true;return;}const p=curr();document.body.dataset.theme=p.theme;document.body.dataset.style=p.style;renderNav();$('#breadcrumbs').innerHTML=`Zork <span>/</span> ${esc(titles[route]||'Início')}`;$('#today-tag').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'short'});let html='';switch(route){case 'home':html=homeView();break;case 'tasks':html=tasksView();break;case 'ideas':html=ideasView();break;case 'calculator':html=calculatorView();break;case 'notes':html=notesView();break;case 'sheets':html=sheetsView();break;case 'calendar':html=calendarView();break;case 'invest':html=investView();break;case 'mix':html=mixView();break;case 'donation':html=donationView();break;case 'help':html=helpView();break;case 'settings':html=settingsView();break;}$('#main').innerHTML=html;editPending=false;}
function isEditing(){const e=document.activeElement;return e&&$('#main')?.contains(e)&&(e.matches('input:not([type=checkbox]),textarea,[contenteditable=true]')||e.closest('[contenteditable=true]'))}
function refreshLater(){if(isEditing()){editPending=true;return}render()}
function newTask(title,date='',priority='normal'){db.save('task',{title,done:false,date,priority});render()}
function taskRow(t,small=false){return `<div class="${small?'task-line':'list-card'}"><input class="check-ui" type="checkbox" aria-label="Concluir ${esc(t.title)}" data-task-toggle="${esc(t.id)}" ${t.done?'checked':''}><div class="${small?'task-title':'grow'} ${t.done?'done task-title':''}">${small?esc(t.title):`<strong class="${t.done?'task-title done':''}">${esc(t.title)}</strong><small>${t.date?fmtDate(t.date):'Sem prazo'} · ${t.priority==='high'?'Alta prioridade':t.priority==='low'?'Baixa prioridade':'Prioridade normal'}</small>`}</div>${small?(t.date?`<span class="task-date">${esc(t.date.slice(5))}</span>`:''):`<button class="icon-btn" aria-label="Excluir" data-action="delete-item" data-id="${t.id}">${ic('trash',15)}</button>`}</div>`}
function homeView(){const tasks=db.list('task'),completed=tasks.filter(t=>t.done).length,notes=db.list('note'),ideas=db.list('idea'),events=db.list('event'),invest=db.list('deposit').reduce((s,x)=>s+Number(x.amount||0),0),toDo=tasks.filter(t=>!t.done).slice(0,5);return `<section class="hero fade-rise"><div class="hero-inner"><div class="eyebrow">SEJA BEM-VINDO AO SEU ESPAÇO</div><h1>Organize suas ideias.<br>Construa seu amanhã.</h1><p>Obrigado por fazer parte do Zork Organiza. Criei este espaço para facilitar o dia a dia, transformar planos em ações e ajudar cada pessoa a evoluir no próprio ritmo.</p><button class="btn btn-primary" data-route="tasks">Começar a organizar ${ic('arrow')}</button></div><div class="hero-decor">Z</div></section>
<div class="stats-grid fade-rise"><div class="card stat-card"><div class="stat-icon">${ic('check')}</div><div class="stat-number">${completed}<span class="muted" style="font-size:16px"> / ${tasks.length}</span></div><div class="stat-label">Tarefas concluídas</div></div><div class="card stat-card"><div class="stat-icon">${ic('lightbulb')}</div><div class="stat-number">${ideas.length}</div><div class="stat-label">Ideias registradas</div></div><div class="card stat-card"><div class="stat-icon">${ic('note')}</div><div class="stat-number">${notes.length+db.list('document').length}</div><div class="stat-label">Anotações salvas</div></div><div class="card stat-card"><div class="stat-icon">${ic('invest')}</div><div class="stat-number" style="font-size:21px">${money(invest)}</div><div class="stat-label">Aportes registrados</div></div></div>
<div class="section-head"><h2>Seu dia, de forma simples</h2><button class="btn btn-small" data-route="help">Conhecer funções ${ic('chevron')}</button></div>
<div class="dashboard-grid"><section class="card"><div class="card-head"><h3>Tarefas em andamento</h3><button class="btn btn-small" data-route="tasks">Ver todas</button></div><div class="form-row" style="justify-content:space-between;margin-bottom:13px"><span class="muted tiny">${completed} de ${tasks.length} concluídas</span><span class="text-accent tiny">${tasks.length?Math.round(completed/tasks.length*100):0}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${tasks.length?completed/tasks.length*100:0}%"></div></div><div style="margin-top:15px">${toDo.length?toDo.map(t=>taskRow(t,true)).join(''):empty('Tudo em dia','Adicione sua primeira tarefa em Rotinas.')}</div></section><section class="card"><div class="card-head"><h3>Seu espaço, suas ferramentas</h3></div><div class="feature-list"><div class="feature-item"><span class="feature-icon">✦</span><div><strong>Planejamento em um só lugar</strong><p>Rotinas, anotações, planilhas e eventos sempre à mão.</p></div></div><div class="feature-item"><span class="feature-icon">⌘</span><div><strong>Personalização completa</strong><p>Quatro paletas e três estilos de interface.</p></div></div><div class="feature-item"><span class="feature-icon">☁</span><div><strong>Seus dados com você</strong><p>Backup local ou sincronização em tempo real com conta configurada.</p></div></div></div></section></div>`}
function tasksView(){const all=db.list('task'),shown=all.filter(t=>(statusTasks==='all'||(statusTasks==='done'===!!t.done))&&(!searchTasks||t.title.toLowerCase().includes(searchTasks.toLowerCase()))),done=all.filter(t=>t.done).length;return `${heading('Suas rotinas','Organize tarefas, defina prazos e marque cada pequena vitória.')}
<div class="split-grid"><section class="panel"><h3>Nova tarefa</h3><form id="task-form" class="stack"><div><label class="form-label">O que precisa ser feito?</label><input class="form-input" name="title" placeholder="Ex.: Estudar por 30 minutos" maxlength="180" required></div><div class="form-grid"><div><label class="form-label">Data (opcional)</label><input class="form-input" type="date" name="date"></div><div><label class="form-label">Prioridade</label><select class="form-select" name="priority"><option value="normal">Normal</option><option value="high">Alta</option><option value="low">Baixa</option></select></div></div><button class="btn btn-primary" type="submit">${ic('plus')} Adicionar tarefa</button></form></section><section class="panel"><div class="eyebrow">SEU PROGRESSO</div><div class="stat-number" style="font-size:40px">${all.length?Math.round(done/all.length*100):0}%</div><p class="muted">${done} de ${all.length} atividades concluídas</p><div class="progress-track" style="margin:18px 0 20px"><div class="progress-fill" style="width:${all.length?done/all.length*100:0}%"></div></div><p class="muted tiny">Constância é melhor que perfeição. Continue no seu ritmo.</p></section></div>
<div class="section-head"><h2>Lista de tarefas</h2>${pill(`${all.length} tarefas`)}</div><div class="toolbar"><input class="form-input search" id="task-search" value="${esc(searchTasks)}" placeholder="Pesquisar tarefa..."><div class="segmented">${[['all','Todas'],['open','Pendentes'],['done','Feitas']].map(([k,v])=>`<button data-task-filter="${k}" class="${statusTasks===k?'selected':''}">${v}</button>`).join('')}</div></div><div class="item-list">${shown.length?shown.map(t=>taskRow(t)).join(''):empty('Nenhuma tarefa encontrada','Você pode adicionar uma tarefa usando o formulário acima.')}</div>`}
function ideasView(){const items=db.list('idea');return `${heading('Banco de ideias','Capture tudo o que vier à mente e transforme pensamentos em projetos.')}
<div class="split-grid"><section class="panel"><h3>Registrar uma ideia</h3><form id="idea-form" class="stack"><input class="form-input" name="title" placeholder="Nome da ideia" required maxlength="140"><textarea class="form-textarea" name="description" placeholder="Descreva sua ideia..."></textarea><select class="form-select" name="category"><option>Projeto</option><option>Conteúdo</option><option>Pessoal</option><option>Outro</option></select><button class="btn btn-primary" type="submit">${ic('plus')} Guardar ideia</button></form></section><section class="panel"><div class="eyebrow">ESPACO CRIATIVO</div><h2>Grandes projetos começam com uma anotação.</h2><p class="muted" style="line-height:1.8">Guarde ideias de vídeos, negócios, estudos e qualquer pensamento que você não queira esquecer.</p><div class="stat-number">${items.length}</div><p class="muted tiny">ideias no seu mural</p></section></div><div class="section-head"><h2>Minhas ideias</h2></div><div class="note-grid">${items.length?items.map(i=>`<div class="card"><div class="card-head">${pill(i.category||'Projeto')}<button class="icon-btn" data-action="delete-item" data-id="${i.id}">${ic('trash',15)}</button></div><h3>${esc(i.title)}</h3><p class="muted" style="white-space:pre-wrap;line-height:1.7;font-size:12px">${esc(i.description)}</p><span class="tiny muted">${new Date(i.createdAt).toLocaleDateString('pt-BR')}</span></div>`).join(''):empty('Seu mural ainda está vazio','Registre uma ideia para começar.')}</div>`}
function calcBody(mini=false){return `<div class="calc ${mini?'calc-mini':''}"><div class="calc-display"><div class="calc-sub" id="calc-history">${esc(calcHist)}</div><div class="calc-value" id="calc-current">${esc(calcText)}</div></div><div class="calc-keys">${['AC','(',')','÷','7','8','9','×','4','5','6','−','1','2','3','+','%','0','.','='].map(v=>`<button class="calc-key ${['AC','(',')','÷','×','−','+','%'].includes(v)?'function':''} ${v==='='?'equals':''}" data-calc="${v}">${v}</button>`).join('')}</div></div>`}
function calculatorView(){return `${heading('Calculadora','Faça suas contas do dia a dia com agilidade. Aceita teclado e operações matemáticas.')}
<div class="split-grid"><div class="panel">${calcBody()}</div><div class="panel"><h3>Um pouco mais de precisão</h3><p class="muted" style="font-size:13px;line-height:1.9">Use parênteses, porcentagem, multiplicação, divisão e exponenciação (tecla ^). Digite com seu teclado quando a calculadora estiver aberta.</p><div class="notice"><strong>Exemplos:</strong> 250 × 15% = 37,5 | (20 + 30) ÷ 2 = 25.</div></div></div>`}
function notesView(){if(noteTab==='word'&&activeDoc)return wordEditorView();const actions=`<button class="btn btn-primary" data-action="new-${noteTab==='keep'?'note':'doc'}">${ic('plus')} Nova ${noteTab==='keep'?'nota':'página'}</button>`;return `${heading('Anotações','Rascunhos rápidos ou documentos completos — tudo salvo automaticamente.',actions)}<div class="toolbar"><div class="segmented"><button data-notetab="keep" class="${noteTab==='keep'?'selected':''}">Bloco de notas</button><button data-notetab="word" class="${noteTab==='word'?'selected':''}">Word / Editor</button></div></div>${noteTab==='keep'?keepView():wordShelfView()}`}
function keepView(){const notes=db.list('note').sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||(b.createdAt-a.createdAt));return `<div class="note-grid">${notes.length?notes.map(n=>`<article class="note-card" data-color="${esc(n.color||'default')}"><div class="note-top"><span class="tiny muted">${n.pinned?'★ Fixada':'Nota rápida'}</span><button class="icon-btn" data-action="pin-note" data-id="${n.id}" aria-label="Fixar">${ic('star',14)}</button></div><input class="note-title" data-edit="note" data-field="title" data-id="${n.id}" placeholder="Título da nota" value="${esc(n.title)}" maxlength="150"><textarea class="note-content" data-edit="note" data-field="body" data-id="${n.id}" placeholder="Escreva aqui...">${esc(n.body)}</textarea><div class="note-foot"><div class="color-row">${[['default','#8e8b95'],['rose','#c67696'],['lavender','#a589d8'],['sage','#82b7a2'],['gold','#e3ba71']].map(([k,c])=>`<button class="color-dot ${n.color===k?'current':''}" style="background:${c}" title="Cor ${k}" data-action="note-color" data-id="${n.id}" data-color="${k}"></button>`).join('')}</div><button data-action="delete-item" data-id="${n.id}" aria-label="Excluir nota">${ic('trash',15)}</button></div></article>`).join(''):empty('Nenhuma anotação ainda','Clique em Nova nota para criar seu primeiro bloco.')}</div>`}
function wordShelfView(){const docs=db.list('document'),visible=showAllDocs?docs:docs.slice(0,10);return `<div class="shelf"><div class="card-head"><h3>Seus documentos</h3>${pill(`${docs.length} páginas`)}</div><div class="shelf-grid">${visible.map(d=>`<button class="shelf-doc" data-action="open-doc" data-id="${d.id}"><span class="doc-symbol">W</span><span><strong>${esc(d.title||'Sem título')}</strong><small>${new Date(d.updatedAt).toLocaleDateString('pt-BR')}</small></span></button>`).join('')}${!docs.length?'<div style="grid-column:1/-1">'+empty('Sua prateleira está vazia','Crie um documento para começar.')+'</div>':''}</div>${docs.length>10?`<div style="text-align:center;margin-top:19px"><button class="btn" data-action="toggle-docs">${showAllDocs?'Mostrar menos':`Ver mais (${docs.length-10})`}</button></div>`:''}</div>`}
function cleanHTML(html){const host=document.createElement('div');host.innerHTML=String(html??'');const allowed=new Set(['P','DIV','BR','STRONG','B','I','EM','U','S','H1','H2','H3','H4','UL','OL','LI','SPAN','FONT','BLOCKQUOTE','A','TABLE','TBODY','THEAD','TR','TD','TH']);const blocked=new Set(['SCRIPT','STYLE','SVG','MATH','IMG','IFRAME','OBJECT','FORM','INPUT','BUTTON','VIDEO','AUDIO','META','LINK','TEMPLATE','EMBED']);const walk=node=>{for(const child of [...node.children]){if(blocked.has(child.tagName)){child.remove();continue}walk(child);if(!allowed.has(child.tagName)){child.replaceWith(...child.childNodes);continue}for(const att of [...child.attributes]){if(att.name==='style'){const styles=att.value.split(';').map(x=>x.trim()).filter(x=>/^(color|background-color|font-size|font-family|text-align|font-weight|text-decoration)\s*:/i.test(x)&&!/(url\(|expression|javascript:|[<>])/i.test(x));if(styles.length)child.setAttribute('style',styles.join(';'));else child.removeAttribute('style')}else if(child.tagName==='FONT'&&((att.name==='color'&&/^(#[0-9a-f]{3,8}|rgb\([0-9, ]+\))$/i.test(att.value))||(att.name==='face'&&/^(Arial|Georgia|Times New Roman|Verdana|Courier New)$/i.test(att.value))||(att.name==='size'&&/^[1-7]$/.test(att.value)))){}else if(att.name==='href'&&child.tagName==='A'&&/^https?:\/\//i.test(att.value)){child.setAttribute('rel','noopener noreferrer');child.setAttribute('target','_blank')}else child.removeAttribute(att.name)}walk(child)}};walk(host);return host.innerHTML}
function wordEditorView(){const doc=db.get(activeDoc);if(!doc){activeDoc=null;return notesView()}return `${heading('Editor de documentos','Formatação, texto, cores e salvamento automático.',`<button class="btn" data-action="back-doc">${ic('left')} Voltar</button><button class="btn" data-action="download-doc">${ic('download')} HTML</button><button class="btn" data-action="print-doc">Imprimir</button><button class="btn btn-danger" data-action="delete-item" data-id="${doc.id}">${ic('trash')} Excluir</button>`)}<div class="word-frame"><div class="word-menu"><div class="form-row" style="margin-bottom:12px"><input class="form-input" id="word-title" value="${esc(doc.title)}" maxlength="160" aria-label="Título do documento"><span class="tiny muted" id="word-status">Salvo automaticamente</span></div><div class="word-controls"><select data-word-font aria-label="Fonte"><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Times New Roman">Times New Roman</option><option value="Verdana">Verdana</option><option value="Courier New">Courier New</option></select><select data-word-size aria-label="Tamanho"><option value="2">12px</option><option value="3" selected>14px</option><option value="4">18px</option><option value="5">24px</option><option value="6">30px</option></select><button class="icon-btn" title="Negrito" data-word-cmd="bold"><b>B</b></button><button class="icon-btn" title="Itálico" data-word-cmd="italic"><i>I</i></button><button class="icon-btn" title="Sublinhado" data-word-cmd="underline"><u>U</u></button><input type="color" value="#1d2330" data-word-color title="Cor do texto"><button class="icon-btn" title="Alinhar à esquerda" data-word-cmd="justifyLeft">☰</button><button class="icon-btn" title="Centralizar" data-word-cmd="justifyCenter">≡</button><button class="icon-btn" title="Lista" data-word-cmd="insertUnorderedList">•</button><button class="icon-btn" title="Desfazer" data-word-cmd="undo">↶</button><button class="icon-btn" title="Refazer" data-word-cmd="redo">↷</button></div></div><div class="word-page-wrap"><div class="word-page" id="word-editor" contenteditable="true" spellcheck="true" aria-label="Texto do documento">${cleanHTML(doc.html||'<p>Comece a escrever...</p>')}</div></div></div>`}
function newBook(title='Minha planilha'){const b=db.save('book',{title,rows:50,cols:14,sheets:[{name:'Página 1',cells:{}}]});activeBook=b.id;activeSheet=0;activeCell='A1';render()}
function sheetsView(){if(activeBook)return sheetEditorView();const books=db.list('book');return `${heading('Planilhas','Organize tabelas, faça cálculos com fórmulas e exporte em CSV.',`<button class="btn btn-primary" data-action="new-book">${ic('plus')} Nova planilha</button>`)}<div class="sheet-list-grid">${books.length?books.map(b=>`<button class="card book-card" data-action="open-book" data-id="${b.id}" style="text-align:left;color:inherit"><div class="book-icon">▦</div><h3>${esc(b.title)}</h3><p>${b.sheets.length} ${b.sheets.length>1?'páginas':'página'} · Atualizada em ${new Date(b.updatedAt).toLocaleDateString('pt-BR')}</p></button>`).join(''):empty('Ainda não há planilhas','Crie uma planilha para preencher suas primeiras células.')}</div>`}
function sheetEditorView(){const b=db.get(activeBook);if(!b){activeBook=null;return sheetsView()}const sh=b.sheets[activeSheet]||b.sheets[0],cells=sh.cells;const cols=Math.min(b.cols,40),rows=Math.min(b.rows,300);let table=`<div class="sheet-wrap"><table class="sheet-grid"><thead><tr><th class="row-number"></th>`;for(let c=0;c<cols;c++)table+=`<th>${colName(c)}</th>`;table+='</tr></thead><tbody>';for(let r=1;r<=rows;r++){table+=`<tr><th class="row-number">${r}</th>`;for(let c=0;c<cols;c++){const addr=colName(c)+r,raw=String(cells[addr]||''),val=cellValue(cells,addr);table+=`<td><input data-cell="${addr}" aria-label="Célula ${addr}" data-raw="${esc(raw)}" value="${esc(val)}" autocomplete="off" spellcheck="false"></td>`}table+='</tr>'}table+='</tbody></table></div>';
return `${heading('Editor de planilhas','Fórmulas como =SUM(A1:A5), =AVERAGE(A1:A5) e =A1*B1.',`<button class="btn" data-action="back-book">${ic('left')} Voltar</button><button class="btn" data-action="export-csv">${ic('download')} CSV</button><button class="btn" data-action="import-csv">${ic('upload')} Importar CSV</button><button class="btn btn-danger" data-action="delete-item" data-id="${b.id}">${ic('trash')}</button>`)}<input type="file" id="csv-file" hidden accept=".csv,text/csv"><div class="form-row" style="margin-bottom:12px"><input class="form-input" id="book-title" maxlength="160" value="${esc(b.title)}" style="max-width:320px"><span class="tiny muted">Salvo automaticamente</span></div><div class="formula-bar"><div class="cell-label" id="cell-label">${activeCell}</div><div class="muted" style="font-weight:800">ƒx</div><input class="form-input" id="formula-value" value="${esc(cells[activeCell]||'')}" aria-label="Barra de fórmulas"></div>${table}<div class="sheet-tabs">${b.sheets.map((sh,i)=>`<button class="btn btn-small ${activeSheet===i?'active':''}" data-sheet="${i}">${esc(sh.name)}</button>`).join('')}<button class="icon-btn" data-action="add-sheet" title="Nova página">${ic('plus')}</button><button class="btn btn-small" data-action="rename-sheet">Renomear aba</button><button class="btn btn-small" data-action="add-rows">+ 20 linhas</button><button class="btn btn-small" data-action="add-cols">+ 5 colunas</button></div><div class="notice">Editor de planilhas básico: operações, referências e algumas funções matemáticas. Não inclui macros, gráficos avançados, tabelas dinâmicas nem todos os recursos do Microsoft Excel. Até 300 linhas × 40 colunas por aba nesta versão.</div>`}
function eventsOn(day){return db.list('event').filter(e=>e.day===day)}
function calendarView(){const y=selectedYear,m=selectedMonth,first=new Date(y,m,1).getDay(),nDays=new Date(y,m+1,0).getDate();const events=db.list('event');const marked=new Set(events.map(e=>e.day));let buttons='';for(let i=0;i<42;i++){const day=i-first+1,valid=day>0&&day<=nDays,date=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;buttons+=`<button class="day ${valid?'':'muted-day'} ${date===localDate()?'today':''} ${selectedDay===date?'selected':''}" ${valid?`data-day="${date}"`:''} aria-label="${valid?date:'Fora do mês'}">${valid?day:''}${valid&&marked.has(date)?'<span class="event-dot"></span>':''}</button>`}const chosen=eventsOn(selectedDay);return `${heading('Datas e eventos','Marque compromissos no calendário. Os dias com anotações recebem um ponto vermelho.')}
<div class="calendar-layout"><div class="panel"><div class="calendar-toolbar"><div class="form-row"><button class="icon-btn" data-action="month-prev" aria-label="Mês anterior">${ic('left')}</button><button class="icon-btn" data-action="month-next" aria-label="Próximo mês">${ic('chevron')}</button></div><h2 style="text-transform:capitalize">${mName(y,m)}</h2><button class="btn btn-small" data-action="month-today">Hoje</button></div><div class="calendar-grid">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>`<div class="weekday">${d}</div>`).join('')}${buttons}</div></div><aside class="panel calendar-side"><div class="eyebrow">DIA SELECIONADO</div><h3>${fmtDate(selectedDay)}</h3><div class="divider"></div><h3 style="font-size:13px">Compromissos (${chosen.length})</h3>${chosen.map(e=>`<div class="event-entry"><div class="form-row" style="justify-content:space-between"><strong>${esc(e.title)}</strong><button class="icon-btn" data-action="delete-item" data-id="${e.id}" aria-label="Excluir">${ic('trash',13)}</button></div><p>${esc(e.description||'Sem descrição')}</p></div>`).join('')||'<p class="muted tiny">Sem eventos para este dia.</p>'}<div class="divider"></div><form id="event-form" class="stack"><div><label class="form-label">Adicionar evento</label><input class="form-input" name="title" placeholder="Título do evento" required maxlength="140"></div><textarea class="form-textarea" name="description" placeholder="Descrição do que vai acontecer..."></textarea><button type="submit" class="btn btn-primary">${ic('plus')} Salvar neste dia</button></form></aside></div>`}
function startDate(year,idx){return new Date(year,idx,1)}
function monthsList(){const p=curr(),start=Number(p.investStartYear)||new Date().getFullYear();return Array.from({length:Number(p.monthsCount)||12},(_,i)=>({year:start+Math.floor(i/12),month:i%12}))}
function depositId(y,m,k){return `${y}-${String(m+1).padStart(2,'0')}-${k}`}
function depositAmount(y,m,k){return db.list('deposit').find(r=>r.period===depositId(y,m,k))?.amount||0}
function depositsTotal(){return db.list('deposit').reduce((s,r)=>s+Number(r.amount||0),0)}
function investmentForecast(){const p=curr();const rate=annualRate(p);let periods=Number(p.investYears)*12;return forecast({initial:p.investInitial,monthly:p.investMonthly,months:periods,annual:rate})}
function investView(){return `${heading('Investimentos','Controle seus aportes e simule juros compostos com taxas definidas por você.')}<div class="toolbar"><div class="segmented"><button data-invest-tab="planner" class="${investTab==='planner'?'selected':''}">Meus aportes</button><button data-invest-tab="calculator" class="${investTab==='calculator'?'selected':''}">Calculadora de investimentos</button></div></div>${investTab==='planner'?plannerView():investCalcView()}`}
function plannerView(){const p=curr(),arr=monthsList(),weekly=p.investMode==='weekly',total=depositsTotal();let saved='';for(const {year,month} of arr){const n=new Date(year,month+1,0).getDate(),count=weekly?Math.ceil(n/7):1;let ins='';for(let k=1;k<=count;k++){const key=weekly?`w${k}`:'month',a=depositAmount(year,month,key),lbl=weekly?(k<=4?`Semana ${k} · ${1+(k-1)*7}–${Math.min(k*7,n)}`:`Dias ${29}–${n}`):'Aporte mensal';ins+=`<div class="week-row"><label for="${year}-${month}-${key}">${lbl}</label><input type="number" min="0" step="0.01" class="form-input" id="${year}-${month}-${key}" data-deposit="${depositId(year,month,key)}" value="${a||''}" placeholder="R$ 0,00"></div>`}let sum=0;for(let k=1;k<=count;k++)sum+=Number(depositAmount(year,month,weekly?`w${k}`:'month'));saved+=`<div class="card month-card"><h3 style="text-transform:capitalize">${mName(year,month)}</h3>${ins}<div class="month-total">${money(sum)}</div></div>`}
return `<div class="stats-grid" style="margin:0 0 17px"><div class="card stat-card"><div class="stat-icon">${ic('invest')}</div><div class="stat-number" style="font-size:23px">${money(total)}</div><div class="stat-label">Total registrado</div></div><div class="card stat-card"><div class="stat-icon">${ic('calendar')}</div><div class="stat-number">${arr.length}</div><div class="stat-label">Meses no planejamento</div></div><div class="card stat-card"><div class="stat-icon">${ic('check')}</div><div class="stat-number">${db.list('deposit').filter(r=>r.amount>0).length}</div><div class="stat-label">Aportes realizados</div></div><div class="card stat-card"><div class="stat-icon">${ic('calculator')}</div><div style="font-size:12px;line-height:1.5;font-weight:700">Simule o rendimento dos seus aportes</div><button class="btn btn-small" style="margin-top:8px" data-invest-tab="calculator">Calcular ${ic('chevron')}</button></div></div>
<div class="panel" style="margin-bottom:20px"><div class="form-row" style="justify-content:space-between;flex-wrap:wrap"><div><h3 style="margin-bottom:4px">Plano de economia</h3><p class="muted tiny no-margin">Organize depósitos por mês ou semana. Meses novos podem ser adicionados sem um limite fixo de anos.</p></div><div class="segmented"><button data-mode="weekly" class="${weekly?'selected':''}">Semanal</button><button data-mode="monthly" class="${!weekly?'selected':''}">Mensal</button></div></div><div class="form-row" style="margin-top:16px;flex-wrap:wrap"><label class="mini-label" for="invest-start-year">Ano inicial</label><input class="form-input" id="invest-start-year" type="number" min="2000" max="2200" value="${p.investStartYear}" style="max-width:105px"><button class="btn btn-small" data-action="extend-months">${ic('plus')} Adicionar 12 meses</button><button class="btn btn-small" data-action="reduce-months" ${arr.length<=12?'disabled':''}>Remover últimos 12</button></div></div><div class="monthly-grid">${saved}</div><div class="notice" style="margin-top:17px">Cada valor é um aporte que você registra manualmente. Alterações são salvas automaticamente. O total soma todos os aportes registrados, inclusive os de períodos que não estão visíveis na tela.</div>`}
function investCalcView(){const p=curr(),res=investmentForecast(),rate=annualRate(p),months=Number(p.investYears)*12;return `<div class="invest-grid"><section class="panel"><h3>Simulador de juros compostos</h3><p class="muted tiny" style="line-height:1.6">Insira taxas anuais de referência manualmente. Não são cotações em tempo real.</p><div class="form-grid"><div class="form-group"><label class="form-label">Tipo de investimento</label><select class="form-select" data-pref="investType"><option value="cdb" ${p.investType==='cdb'?'selected':''}>CDB (% do CDI)</option><option value="cdi" ${p.investType==='cdi'?'selected':''}>CDI</option><option value="selic" ${p.investType==='selic'?'selected':''}>Selic</option><option value="tesouro" ${p.investType==='tesouro'?'selected':''}>Tesouro Selic (aprox.)</option><option value="fixed" ${p.investType==='fixed'?'selected':''}>Taxa fixa anual</option></select></div><div class="form-group"><label class="form-label">Taxa de referência anual (%)</label><input class="form-input" data-pref="annualBase" type="number" min="0" max="150" step="0.01" value="${p.annualBase}"></div><div class="form-group"><label class="form-label">Percentual da taxa (%)</label><input class="form-input" data-pref="percentCDI" type="number" min="0" max="500" step="1" value="${p.percentCDI}" ${p.investType==='fixed'?'disabled':''}></div><div class="form-group"><label class="form-label">Prazo (anos)</label><input class="form-input" data-pref="investYears" type="number" min="1" max="100" value="${p.investYears}"></div><div class="form-group"><label class="form-label">Aporte inicial (R$)</label><input class="form-input" data-pref="investInitial" type="number" min="0" step="0.01" value="${p.investInitial}"></div><div class="form-group"><label class="form-label">Aporte por mês (R$)</label><input class="form-input" data-pref="investMonthly" type="number" min="0" step="0.01" value="${p.investMonthly}"></div></div><div class="notice">Taxa usada na projeção: <strong>${rate.toLocaleString('pt-BR',{maximumFractionDigits:2})}% ao ano.</strong> Prazo de ${months} meses. Aportes considerados no fim de cada mês.</div><button class="btn" style="margin-top:14px" data-action="fill-monthly">Usar média dos meus aportes na simulação</button></section><section class="result-card"><div class="eyebrow">PROJEÇÃO ESTIMADA</div><div class="mini-label">Patrimônio bruto projetado</div><div class="result-main">${money(res.total)}</div><div class="progress-track" style="margin-top:22px;height:11px"><div class="progress-fill" style="width:${res.total?Math.max(1,100*res.contributions/res.total):0}%"></div></div><div class="form-row" style="justify-content:space-between;margin-top:9px"><span class="tiny muted">Aportes</span><span class="tiny muted">Rendimento</span></div><div class="result-split"><div><span class="mini-label">Dinheiro aplicado</span><strong>${money(res.contributions)}</strong></div><div><span class="mini-label">Juros brutos</span><strong class="text-mint">${money(res.profit)}</strong></div><div><span class="mini-label">IR estimado sobre lucro</span><strong>${money(res.estimatedIR)}</strong></div><div><span class="mini-label">Valor líquido estimado</span><strong>${money(res.net)}</strong></div></div><div class="divider"></div><p class="tiny muted" style="line-height:1.8">Estimativa simplificada, sem IOF, custos, taxas adicionais, inflação ou impostos específicos por aporte. No Tesouro Selic e em CDBs o rendimento real pode variar. Não é recomendação financeira.</p></section></div>`}
function widget(id){if(id==='tasks'){const t=db.list('task').slice(0,6);return `<div class="widget-content">${t.length?t.map(x=>taskRow(x,true)).join(''):empty('Sem tarefas','Crie uma tarefa em Rotinas.')}</div>`}if(id==='calculator')return calcBody(true);if(id==='notes'){const n=db.list('note').slice(0,5);return `<div class="widget-content">${n.length?n.map(x=>`<div class="list-card"><span>▤</span><div class="grow"><strong>${esc(x.title||'Sem título')}</strong><small>${esc(x.body.slice(0,80))}</small></div></div>`).join(''):empty('Sem notas','Crie notas no bloco de anotações.')}</div>`}if(id==='invest')return `<div><span class="mini-label">Total guardado</span><div class="result-main" style="font-size:28px">${money(depositsTotal())}</div><p class="muted tiny">Aportes registrados nos seus planejamentos.</p></div>`;if(id==='calendar'){const ev=db.list('event').filter(x=>x.day>=localDate()).sort((a,b)=>a.day.localeCompare(b.day)).slice(0,5);return `<div class="widget-content">${ev.length?ev.map(x=>`<div class="list-card"><div class="grow"><strong>${esc(x.title)}</strong><small>${fmtDate(x.day)}</small></div></div>`).join(''):empty('Nenhum evento próximo','Adicione datas no calendário.')}</div>`}if(id==='ideas'){const ids=db.list('idea').slice(0,5);return `<div class="widget-content">${ids.length?ids.map(x=>`<div class="list-card"><div class="grow"><strong>${esc(x.title)}</strong><small>${esc(x.category)}</small></div></div>`).join(''):empty('Sem ideias','Seu mural de ideias está vazio.')}</div>`}if(id==='sheets'||id==='word'){const l=db.list(id==='word'?'document':'book').slice(0,5);return `<div class="widget-content">${l.length?l.map(x=>`<div class="list-card"><div class="grow"><strong>${esc(x.title)}</strong></div></div>`).join(''):empty('Sem arquivos','Crie um arquivo para visualizá-lo.')}</div>`}return ''}
const mixOptions=[['tasks','Rotinas'],['calculator','Calculadora'],['notes','Bloco de notas'],['word','Word'],['sheets','Planilhas'],['calendar','Datas'],['invest','Investimentos'],['ideas','Ideias']];
function mixView(){const active=curr().mix||[];return `${heading('Área mista','Escolha quatro ferramentas para acompanhar tudo em uma única tela.')}
<div class="panel" style="margin-bottom:20px"><div class="card-head"><h3>Monte seu painel</h3>${pill(`${active.length}/4 espaços`)}</div><div class="toolbar" style="margin-bottom:0">${mixOptions.map(([id,label])=>`<button class="btn btn-small ${active.includes(id)?'btn-primary':''}" data-mix="${id}" ${!active.includes(id)&&active.length>=4?'disabled':''}>${active.includes(id)?'✓':'+'} ${label}</button>`).join('')}</div></div><div class="mix-grid">${active.map(id=>`<div class="card mix-widget"><div class="card-head"><h3>${esc(mixOptions.find(x=>x[0]===id)?.[1]||id)}</h3><button class="btn btn-small" data-route="${id==='word'?'notes':id==='sheets'?'sheets':id}">Abrir ${ic('arrow',13)}</button></div>${widget(id)}</div>`).join('')}${!active.length?empty('Escolha até quatro ferramentas','Seu painel personalizado aparecerá aqui.'):''}</div>`}
const themeChoices=[['dark','Dark sólido','#101114','#141519','#23242b','#bca4ff'],['light','Claro','#f5f6f9','#fff','#ececf3','#7357db'],['galaxy','Galáxia clara','#f1eefa','#faf9ff','#e9defb','#7953d7'],['galaxy-night','Galáxia noturna','#111023','#16132a','#2b2545','#c6a4ff']];
function settingsView(){const p=curr(),user=db.currentUser();return `${heading('Configurações','Personalize sua experiência, gerencie seu backup e conecte uma conta.')}
<div class="settings-stack"><section class="panel settings-block"><h3>Acessibilidade e aparência</h3><p>Escolha uma das quatro cores de interface. A alteração se aplica imediatamente a todas as áreas.</p><div class="theme-grid">${themeChoices.map(([key,name,bg,side,surface,accent])=>`<button class="theme-choice ${p.theme===key?'selected':''}" data-theme-choice="${key}"><div class="theme-preview" style="background:${bg}"><div class="tp-side" style="background:${side}"></div><div class="tp-main" style="background:${surface}"><span style="background:${accent}"></span><span style="background:${accent};width:55%"></span></div></div><strong>${name}</strong><small>${p.theme===key?'✓ Selecionado':'Selecionar tema'}</small></button>`).join('')}</div></section>
<section class="panel settings-block"><h3>Estilo de interface</h3><p>Três interpretações visuais: Windows 11 aprimorado, Windows 10 e Windows 7. Funciona em todas as categorias.</p><div class="style-grid">${[['modern','Moderno','Windows 11 · cantos arredondados'],['mid','Intermediário','Windows 10 · linhas equilibradas'],['retro','Clássico','Windows 7 · visual mais tradicional']].map(([key,name,desc])=>`<button class="style-choice ${p.style===key?'selected':''}" data-style-choice="${key}"><strong>${name} ${p.style===key?'✓':''}</strong><small>${desc}</small></button>`).join('')}</div></section>
<section class="panel settings-block"><h3>Conta e sincronização</h3><p>${user?'Sua conta pode sincronizar dados entre dispositivos com o mesmo login.':'Você está no modo visitante: os dados ficam apenas neste navegador, neste dispositivo.'}</p>${user?`<div class="list-card" style="margin-bottom:15px">${ic('user')}<div class="grow"><strong>${esc(user.displayName||user.email||'Conta conectada')}</strong><small>${esc(user.email||'Google')} · ${db.cloudReady()?'Nuvem conectada':'Aguardando sincronização'}</small></div></div><div class="form-row" style="flex-wrap:wrap"><button class="btn" data-action="import-guest">Importar anotações deste navegador</button><button class="btn btn-danger" data-action="logout">${ic('logout')} Sair</button></div>`:`<button class="btn btn-primary" data-action="auth-modal">${ic('user')} Entrar / criar conta</button><p class="muted tiny" style="margin-top:12px">${db.firebaseReady()?'Login com Google e e-mail disponíveis.':'Para habilitar o login, configure seu projeto gratuito no Firebase pelo README.'}</p>`}</section>
<section class="panel settings-block"><h3>Backup e portabilidade</h3><p>Exporte um arquivo JSON completo ou recupere os dados de um backup anterior. Isso também é útil para mudar de aparelho sem conta.</p><div class="form-row" style="flex-wrap:wrap"><button class="btn" data-action="export-json">${ic('download')} Baixar backup (.json)</button><button class="btn" data-action="import-json">${ic('upload')} Restaurar backup (.json)</button></div><input type="file" id="backup-file" hidden accept=".json,application/json"><div class="notice" style="margin-top:15px">Um backup contém suas tarefas, textos, planilhas, eventos, aportes e preferências. Proteja o arquivo: ele pode incluir informações pessoais. Restaurar substitui todos os seus dados atuais.</div></section></div>`}
function donationView(){return `${heading('Donation','Uma ajuda voluntária ao criador do projeto.')}
<div class="donation-layout"><section class="panel"><div class="eyebrow">UMA MENSAGEM DO CRIADOR</div><h2>Pequenos passos também constroem grandes sonhos.</h2><p class="donation-message">Tenho 18 anos e estou tentando mudar minha vida aos poucos. Um dos meus sonhos é me tornar criador de conteúdo no YouTube e construir algo relevante na internet. Como meu computador ainda é limitado, estou começando pelo desenvolvimento de sites e ferramentas que possam ajudar outras pessoas.</p><p class="donation-message">Se este projeto for útil para você e quiser apoiá-lo com qualquer valor, ficarei muito grato. A doação é totalmente opcional — o Zork Organiza continua disponível gratuitamente.</p><button class="btn btn-primary" data-action="scroll-pix">${ic('heart')} Doar via Pix</button><p class="muted tiny" style="margin-top:15px">Obrigado por fazer parte deste começo. ♡</p></section><section class="panel" id="pix-panel"><div class="eyebrow">APOIE VIA PIX</div><h3>Escaneie o QR Code</h3><img class="donation-qr" src="assets/pix-qr.png" alt="QR Code Pix para contribuição voluntária" width="220" height="220"><p class="muted tiny" style="text-align:center">Ou copie o Pix copia e cola:</p><div class="pix-code">${esc(pix)}</div><button class="btn btn-primary" data-action="copy-pix" style="width:100%;margin-top:13px">${ic('copy')} Copiar código Pix</button><div class="notice" style="margin-top:15px">Antes de confirmar o pagamento, verifique os dados do destinatário exibidos pelo seu banco. O Pix pode mostrar o nome civil do recebedor.</div></section></div>`}
const helpItems=[['Rotinas','Crie atividades, escolha uma data e prioridade. Marque a caixa para concluir.'],['Ideias','Anote projetos, vídeos, planos e pensamentos para não perder a inspiração.'],['Calculadora','Realize contas matemáticas com porcentagem, parênteses e operações básicas.'],['Bloco de notas','Faça notas rápidas em cartões coloridos e fixe as mais importantes.'],['Word / Editor','Crie páginas formatadas com fontes, cores, títulos, listas, impressão e exportação HTML.'],['Planilhas','Preencha células e faça contas com funções como SUM, AVERAGE, MIN, MAX e COUNT.'],['Datas e eventos','Navegue entre os meses e adicione eventos: uma marca vermelha sinaliza dias ocupados.'],['Investimentos','Guarde seus aportes por semana ou mês e simule juros com taxas informadas manualmente.'],['Área mista','Escolha quatro módulos para visualizar juntos em um painel.'],['Acessibilidade','Alterne tema escuro, claro e galáxia, além dos estilos moderno, intermediário e clássico.'],['Backup','Sem conta, os dados ficam no navegador. Com Firebase configurado, o login sincroniza pela nuvem.']];
function helpView(){return `${heading('Guia das funções','Entenda rapidamente tudo que você pode fazer no Zork Organiza.')}
<div class="help-grid">${helpItems.map(([title,desc],i)=>`<div class="card help-card"><div class="eyebrow">RECURSO ${String(i+1).padStart(2,'0')}</div><h3>${title}</h3><p>${desc}</p></div>`).join('')}</div><div class="notice" style="margin-top:22px"><strong>Dica importante:</strong> O GitHub Pages hospeda apenas o site. Para login, banco na nuvem e sincronização em tempo real, é necessário configurar Firebase Authentication e Firestore com as regras de segurança incluídas no projeto.</div>`}
function authDialog(){if(!db.firebaseReady()){ask({title:'Conectar sua conta',body:'Antes de usar Google ou e-mail, configure seu aplicativo Firebase no arquivo config.js e publique as regras do Firestore. Consulte o README.',confirm:'Entendi'});return}$('#modal-root').innerHTML=`<div class="modal-overlay"><div class="modal"><div class="modal-head"><h2>Minha conta</h2><button class="icon-btn" data-action="close-modal">${ic('close')}</button></div><p class="muted tiny">Faça login para sincronizar seus dados entre dispositivos.</p><button class="btn" style="width:100%;margin:12px 0 15px" data-action="google-login"><b style="font-size:19px;color:#4285f4">G</b> Continuar com Google</button><div class="divider"></div><div class="auth-tabs"><button class="btn ${authTab==='login'?'btn-primary':''}" data-auth-tab="login">Entrar</button><button class="btn ${authTab==='register'?'btn-primary':''}" data-auth-tab="register">Criar conta</button></div><form id="auth-form" class="stack"><div><label class="form-label">E-mail</label><input class="form-input" type="email" name="email" required autocomplete="email" placeholder="email@gmail.com"></div><div><label class="form-label">Senha</label><input class="form-input" type="password" name="password" required minlength="6" autocomplete="${authTab==='login'?'current-password':'new-password'}" placeholder="No mínimo 6 caracteres"></div><button type="submit" class="btn btn-primary">${authTab==='login'?'Entrar':'Criar minha conta'}</button></form><button class="btn btn-small" data-action="reset-password" style="margin-top:11px">Esqueci minha senha</button><p class="tiny muted" style="line-height:1.6;margin:12px 0 0">Suas anotações de visitante continuam no navegador. Após entrar, use “Importar anotações deste navegador” nas configurações para copiá-las à sua conta.</p></div></div>`}
function sheetCommit(addr,value){const b=db.get(activeBook);if(!b)return;b.sheets[activeSheet].cells[addr]=String(value).slice(0,5000);db.save('book',b);updateGridValues()}
function updateGridValues(){const b=db.get(activeBook);if(!b)return;const cells=b.sheets[activeSheet].cells;$$('[data-cell]').forEach(el=>{const adr=el.dataset.cell;el.dataset.raw=cells[adr]||'';if(document.activeElement!==el)el.value=cellValue(cells,adr)});const f=$('#formula-value');if(f&&document.activeElement!==f)f.value=cells[activeCell]||''}
function restoreWordSelection(){const ed=$('#word-editor');if(!ed)return;ed.focus();if(savedWordRange&&ed.contains(savedWordRange.commonAncestorContainer)){const sel=window.getSelection();sel.removeAllRanges();sel.addRange(savedWordRange)}}
function docSave(){const d=db.get(activeDoc),ed=$('#word-editor');if(!d||!ed)return;db.save('document',{...d,html:cleanHTML(ed.innerHTML),title:$('#word-title')?.value||'Sem título'});if($('#word-status'))$('#word-status').textContent='Salvo automaticamente'}
function updateCalc(){const a=$('#calc-current'),b=$('#calc-history');if(a)a.textContent=calcText;if(b)b.textContent=calcHist}
function calcKey(key){if(key==='AC'){calcText='0';calcHist=''}else if(key==='='){try{const expr=calcText.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-');const ans=compute(expr);calcHist=calcText+' =';calcText=String(ans)}catch{calcHist=calcText;calcText='Erro'}}else if(key==='Backspace'){calcText=calcText.slice(0,-1)||'0'}else if(calcText==='Erro'){calcText=key}else if(calcText==='0'&&(/[\d.(]/.test(key))){calcText=key}else if(calcText.length<90){calcText+=key}updateCalc()}
const commitDeposit=(period,amount)=>{const old=db.list('deposit').find(r=>r.period===period);if(Number(amount)>0)db.save('deposit',{...old,period,amount:Number(amount)});else if(old)db.remove(old.id)};
async function handleAction(el){const act=el.dataset.action,id=el.dataset.id;switch(act){
case 'close-modal':closeModal();break;
case 'auth-modal':authDialog();break;
case 'google-login':try{await db.loginGoogle();closeModal();notify('Autenticação iniciada.')}catch(e){notify('Não foi possível entrar: '+(e.message||e.code))}break;
case 'logout':try{await db.logout();notify('Você saiu da conta.')}catch(e){notify(e.message)}break;
case 'reset-password':{const email=$('#auth-form [name=email]')?.value||prompt('Qual é o seu e-mail?');if(!email)return;try{await db.resetPassword(email);notify('Se o endereço estiver cadastrado, você receberá instruções.')}catch(e){notify(e.message)}break}
case 'new-note':db.save('note',{title:'Nova nota',body:'',color:'default',pinned:false});render();break;
case 'new-doc':{const d=db.save('document',{title:'Documento sem título',html:'<p>Comece a escrever...</p>'});activeDoc=d.id;render();break}
case 'open-doc':activeDoc=id;render();break;
case 'back-doc':docSave();activeDoc=null;render();break;
case 'toggle-docs':showAllDocs=!showAllDocs;render();break;
case 'pin-note':{const n=db.get(id);if(n)db.save('note',{...n,pinned:!n.pinned});render();break}
case 'note-color':{const n=db.get(id);if(n)db.save('note',{...n,color:el.dataset.color});render();break}
case 'delete-item':{const item=db.get(id);if(!item)return;ask({title:'Excluir este item?',body:`Deseja excluir “${item.title||item.period||'este item'}”? Esta ação será refletida nos dispositivos conectados.`,confirm:'Excluir',onConfirm:()=>{db.remove(id);if(activeDoc===id)activeDoc=null;if(activeBook===id)activeBook=null;render();notify('Item excluído.')}});break}
case 'download-doc':{const d=db.get(activeDoc);if(d)download(`${(d.title||'documento').replace(/[^\wÀ-ÿ-]+/g,'_')}.html`,`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>${esc(d.title)}</title><style>body{max-width:800px;margin:60px auto;padding:20px;font:16px/1.7 Arial}</style>${cleanHTML($('#word-editor')?.innerHTML||d.html)}`,'text/html');break}
case 'print-doc':{const d=db.get(activeDoc);if(d){const w=window.open('','_blank');if(!w){notify('Permita pop-ups para imprimir.');break}w.document.write(`<!doctype html><html><meta charset="utf-8"><title>${esc(d.title)}</title><style>body{font:14px/1.7 Arial;padding:2cm}</style>${cleanHTML($('#word-editor')?.innerHTML||d.html)}</html>`);w.document.close();w.focus();w.print()}break}
case 'new-book':newBook();break;
case 'open-book':activeBook=id;activeSheet=0;activeCell='A1';render();break;
case 'back-book':activeBook=null;render();break;
case 'add-sheet':{const b=db.get(activeBook);if(b){b.sheets.push({name:`Página ${b.sheets.length+1}`,cells:{}});activeSheet=b.sheets.length-1;db.save('book',b);render()}break}
case 'rename-sheet':{const b=db.get(activeBook);if(!b)return;const name=prompt('Novo nome da aba:',b.sheets[activeSheet].name);if(name?.trim()){b.sheets[activeSheet].name=name.trim().slice(0,40);db.save('book',b);render()}break}
case 'add-rows':case 'add-cols':{const b=db.get(activeBook);if(!b)return;const axis=act==='add-rows'?'rows':'cols',max=axis==='rows'?300:40;b[axis]=Math.min(max,b[axis]+(axis==='rows'?20:5));db.save('book',b);render();if(b[axis]===max)notify(`Limite de ${max} ${axis==='rows'?'linhas':'colunas'} por aba nesta versão.`);break}
case 'export-csv':{const b=db.get(activeBook);if(!b)return;const sh=b.sheets[activeSheet];const lines=[];for(let r=1;r<=b.rows;r++){const line=[];for(let c=0;c<b.cols;c++)line.push(csvEscape(sh.cells[colName(c)+r]||''));lines.push(line.join(';'))}download(`${b.title.replace(/[^\wÀ-ÿ-]+/g,'_')}.csv`,'\ufeff'+lines.join('\r\n'),'text/csv;charset=utf-8');notify('CSV exportado.');break}
case 'import-csv':$('#csv-file')?.click();break;
case 'month-prev':selectedMonth--;if(selectedMonth<0){selectedMonth=11;selectedYear--}selectedDay=`${selectedYear}-${String(selectedMonth+1).padStart(2,'0')}-01`;render();break;
case 'month-next':selectedMonth++;if(selectedMonth>11){selectedMonth=0;selectedYear++}selectedDay=`${selectedYear}-${String(selectedMonth+1).padStart(2,'0')}-01`;render();break;
case 'month-today':selectedYear=new Date().getFullYear();selectedMonth=new Date().getMonth();selectedDay=localDate();render();break;
case 'extend-months':db.setPrefs({monthsCount:(Number(curr().monthsCount)||12)+12});render();break;
case 'reduce-months':db.setPrefs({monthsCount:Math.max(12,(Number(curr().monthsCount)||12)-12)});render();break;
case 'fill-monthly':{const d=db.list('deposit'),months=new Set(d.map(x=>x.period.slice(0,7)));const avg=months.size?d.reduce((s,x)=>s+Number(x.amount),0)/months.size:0;db.setPrefs({investMonthly:Number(avg.toFixed(2))});render();notify('Média mensal preenchida na simulação.');break}
case 'export-json':download(`zork-backup-${localDate()}.json`,JSON.stringify(db.allData(),null,2));notify('Backup exportado.');break;
case 'import-json':$('#backup-file')?.click();break;
case 'import-guest':ask({title:'Importar dados de visitante?',body:'As tarefas e documentos armazenados neste navegador serão copiados para sua conta, sem remover os dados existentes.',confirm:'Importar dados',onConfirm:async()=>{try{await db.importGuest();render();notify('Dados copiados para sua conta.')}catch(e){notify(e.message)}}});break;
case 'copy-pix':try{await navigator.clipboard.writeText(pix);notify('Código Pix copiado.')}catch{notify('Não foi possível copiar automaticamente. Selecione o código no cartão.')}break;
case 'scroll-pix':$('#pix-panel')?.scrollIntoView({behavior:'smooth',block:'center'});break;
}}
document.addEventListener('click',async e=>{
 const routeEl=e.target.closest('[data-route]');if(routeEl){navigate(routeEl.dataset.route);return}
 const action=e.target.closest('[data-action]');if(action){await handleAction(action);return}
 const th=e.target.closest('[data-theme-choice]');if(th){db.setPrefs({theme:th.dataset.themeChoice});render();return}
 const st=e.target.closest('[data-style-choice]');if(st){db.setPrefs({style:st.dataset.styleChoice});render();return}
 const tab=e.target.closest('[data-notetab]');if(tab){noteTab=tab.dataset.notetab;activeDoc=null;render();return}
 const it=e.target.closest('[data-invest-tab]');if(it){investTab=it.dataset.investTab;render();return}
 const mode=e.target.closest('[data-mode]');if(mode){db.setPrefs({investMode:mode.dataset.mode});render();return}
 const mix=e.target.closest('[data-mix]');if(mix){const now=[...curr().mix],v=mix.dataset.mix;if(now.includes(v))now.splice(now.indexOf(v),1);else if(now.length<4)now.push(v);db.setPrefs({mix:now});render();return}
 const day=e.target.closest('[data-day]');if(day){selectedDay=day.dataset.day;render();return}
 const sheet=e.target.closest('[data-sheet]');if(sheet){activeSheet=Number(sheet.dataset.sheet);activeCell='A1';render();return}
 const filter=e.target.closest('[data-task-filter]');if(filter){statusTasks=filter.dataset.taskFilter;render();return}
 const calc=e.target.closest('[data-calc]');if(calc){calcKey(calc.dataset.calc);return}
 const word=e.target.closest('[data-word-cmd]');if(word){restoreWordSelection();document.execCommand(word.dataset.wordCmd,false,null);clearTimeout(docTimer);docTimer=setTimeout(docSave,350);return}
 const at=e.target.closest('[data-auth-tab]');if(at){authTab=at.dataset.authTab;authDialog();return}
 if(e.target.closest('#account-mini')||e.target.closest('#account-top')){navigate('settings');return}
 if(e.target.closest('#menu-button')){$('#sidebar').classList.add('open');$('#sidebar-scrim').classList.add('open');return}
 if(e.target.closest('#sidebar-scrim')){$('#sidebar').classList.remove('open');$('#sidebar-scrim').classList.remove('open');return}
 if(e.target.classList.contains('modal-overlay'))closeModal();
});
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-word-cmd]'))e.preventDefault()});
document.addEventListener('selectionchange',()=>{const ed=$('#word-editor'),sel=window.getSelection();if(ed&&sel?.rangeCount&&ed.contains(sel.anchorNode))savedWordRange=sel.getRangeAt(0).cloneRange()});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));if(form.id==='task-form'){if(values.title?.trim())newTask(values.title.trim(),values.date,values.priority)}else if(form.id==='idea-form'){if(values.title?.trim()){db.save('idea',{title:values.title.trim(),description:values.description||'',category:values.category||'Projeto'});render()}}else if(form.id==='event-form'){if(values.title?.trim()){db.save('event',{title:values.title.trim(),description:values.description||'',day:selectedDay});render()}}else if(form.id==='auth-form'){try{await db.loginEmail(values.email,values.password,authTab==='register');closeModal();notify('Bem-vindo à sua conta.')}catch(err){notify(err.code==='auth/email-already-in-use'?'Este e-mail já está cadastrado.':err.message)}}});
document.addEventListener('change',async e=>{const el=e.target;
 if(el.matches('[data-task-toggle]')){const t=db.get(el.dataset.taskToggle);if(t)db.save('task',{...t,done:el.checked});render();return}
 if(el.matches('[data-pref]')){let value=el.value;if(el.type==='number')value=Number(value);db.setPrefs({[el.dataset.pref]:value});refreshLater();return}
 if(el.id==='invest-start-year'){db.setPrefs({investStartYear:Math.max(2000,Math.min(2200,Number(el.value)||2026))});render();return}
 if(el.matches('[data-deposit]')){commitDeposit(el.dataset.deposit,el.value);refreshLater();return}
 if(el.matches('[data-word-font]')){restoreWordSelection();document.execCommand('fontName',false,el.value);docSave();return}
 if(el.matches('[data-word-size]')){restoreWordSelection();document.execCommand('fontSize',false,el.value);docSave();return}
 if(el.matches('[data-word-color]')){restoreWordSelection();document.execCommand('foreColor',false,el.value);docSave();return}
 if(el.id==='backup-file'&&el.files?.[0]){try{const file=el.files[0],data=JSON.parse(await file.text());ask({title:'Restaurar backup?',body:'Todos os dados atuais desta conta ou navegador serão substituídos pelos dados do arquivo selecionado. Faça um backup antes de continuar.',confirm:'Restaurar',onConfirm:async()=>{try{await db.importData(data);render();notify('Backup restaurado.')}catch(err){notify(err.message)}}})}catch(err){notify('Arquivo inválido: '+err.message)}return}
 if(el.id==='csv-file'&&el.files?.[0]){try{const rows=parseCSV((await el.files[0].text()).replace(/^\ufeff/,'')),b=db.get(activeBook),sheet=b?.sheets[activeSheet];if(!sheet)return;rows.slice(0,300).forEach((row,r)=>row.slice(0,40).forEach((val,c)=>{if(val)sheet.cells[colName(c)+(r+1)]=val}));b.rows=Math.max(b.rows,Math.min(300,rows.length));b.cols=Math.max(b.cols,Math.min(40,Math.max(...rows.map(x=>x.length),0)));db.save('book',b);render();notify('CSV importado com sucesso.')}catch(err){notify('Erro ao importar CSV: '+err.message)}return}
});
document.addEventListener('input',e=>{const el=e.target;
 if(el.id==='task-search'){searchTasks=el.value;const matches=db.list('task').filter(t=>(statusTasks==='all'||(statusTasks==='done'===!!t.done))&&t.title.toLowerCase().includes(searchTasks.toLowerCase()));const results=$('.item-list');if(results)results.innerHTML=matches.length?matches.map(t=>taskRow(t)).join(''):empty('Nenhuma tarefa encontrada','Altere a busca ou crie uma nova tarefa.');return}
 if(el.matches('[data-edit=note]')){const n=db.get(el.dataset.id);if(!n)return;db.save('note',{...n,[el.dataset.field]:el.value},450);return}
 if(el.id==='word-editor'){if($('#word-status'))$('#word-status').textContent='Salvando...';clearTimeout(docTimer);docTimer=setTimeout(docSave,450);return}
 if(el.id==='word-title'){clearTimeout(docTimer);docTimer=setTimeout(docSave,450);return}
 if(el.matches('[data-deposit]')){clearTimeout(saveTimer);saveTimer=setTimeout(()=>commitDeposit(el.dataset.deposit,el.value),500);return}
 if(el.id==='book-title'){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{const b=db.get(activeBook);if(b)db.save('book',{...b,title:el.value})},450);return}
 if(el.id==='formula-value'){return}
});
document.addEventListener('focusin',e=>{const el=e.target;if(el.matches('[data-cell]')){const b=db.get(activeBook);if(!b)return;activeCell=el.dataset.cell;el.value=b.sheets[activeSheet].cells[activeCell]||'';if($('#formula-value'))$('#formula-value').value=el.value;if($('#cell-label'))$('#cell-label').textContent=activeCell;el.select()}});
document.addEventListener('focusout',e=>{const el=e.target;
 if(el.matches('[data-cell]')){sheetCommit(el.dataset.cell,el.value);return}
 if(el.id==='formula-value'){sheetCommit(activeCell,el.value);return}
 if(el.id==='book-title'){const b=db.get(activeBook);if(b)db.save('book',{...b,title:el.value});return}
 if(el.id==='word-editor'||el.id==='word-title'){clearTimeout(docTimer);docSave()}
 setTimeout(()=>{if(editPending&&!isEditing())render()},60);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').children.length){closeModal();return}
 if(e.target.id==='formula-value'&&e.key==='Enter'){e.preventDefault();sheetCommit(activeCell,e.target.value);e.target.blur();return}
 if(e.target.matches?.('[data-cell]')&&e.key==='Enter'){e.preventDefault();e.target.blur();const match=activeCell.match(/^([A-Z]+)(\d+)$/);if(match){const next=$(`[data-cell="${match[1]}${Number(match[2])+1}"]`);next?.focus()}return}
 if(route==='calculator'||route==='mix'&&curr().mix.includes('calculator')){if(e.target.matches('input,textarea,[contenteditable=true],select'))return;const map={'*':'×','/':'÷','-':'−','Enter':'=','Backspace':'Backspace','Escape':'AC'};const k=map[e.key]||e.key;if(/[0-9.+()%×÷−^=]/.test(k)&&k.length===1||k==='Backspace'||k==='AC'){e.preventDefault();calcKey(k)}}
});
db.subscribe(kind=>{if(kind==='prefs')document.body.dataset.theme=curr().theme,document.body.dataset.style=curr().style;refreshLater()},(type,error)=>{if(type==='firebase-error')notify('Não foi possível iniciar o Firebase. Confira sua configuração.');if(type==='sync-error')notify('Erro ao sincronizar: verifique o Firebase e as regras.');renderNav()});
$('#menu-button').addEventListener('click',()=>{});
db.initFirebase();
